const STATUS = { draft: ["Draft", "neutral"], sent: ["Sent", "info"], paid: ["Paid", "success"], overdue: ["Overdue", "danger"] };
const [word, tone] = STATUS[invoice.status];

<h2>Invoice {invoice.number} <Badge tone={tone}>{word}</Badge></h2>

<BadgeGroup label="Filters">
  <Badge key="mine" selected={onlyMine} onClick={() => setOnlyMine((v) => !v)}>Assigned to me</Badge>
  {filters.map((f) => (
    <Badge key={f.id} onRemove={() => setFilters((all) => all.filter((x) => x.id !== f.id))} removeLabel="Remove filter">{f.label}</Badge>
  ))}
</BadgeGroup>
